input.query:
WITH test AS (
    SELECT unnest([10, 20, 20, 30]) AS val
),
ranked AS (
    SELECT val, ROW_NUMBER() OVER (ORDER BY val) AS rn
    FROM test
)
SELECT val, rn, AVG(rn) OVER (PARTITION BY val) AS midrank
FROM ranked;
